<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2020 Kaohsiung Tea Culture Exhibition</title>
    <style>
        :root {
            --bg-color: #e8e3d3;
            --text-dark: #2a2722;
            --text-red: #842b23;
            --pin-gold: #a68c53;
            --font-serif: "Noto Serif SC", "SimSun", "STSong", serif;
            --font-en: "Times New Roman", Times, serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: #333;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .poster {
            position: relative;
            width: 800px;
            height: 1130px;
            background-color: var(--bg-color);
            font-family: var(--font-serif);
            color: var(--text-dark);
            overflow: hidden;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        .placeholder {
            border: 2px dashed #999;
            background-color: rgba(0, 0, 0, 0.04);
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            font-size: 12px;
            color: #666;
            font-family: sans-serif;
            padding: 5px;
        }

        /* Top Left - Vertical Text */
        .vert-text {
            position: absolute;
            top: 60px;
            left: 45px;
            color: var(--text-red);
            font-family: var(--font-en);
            font-size: 22px;
            width: 25px;
            word-wrap: break-word;
            text-align: center;
            line-height: 1.05;
            letter-spacing: 2px;
        }

        /* Top Left - Main Title Cluster */
        .main-title-cluster {
            position: absolute;
            top: 70px;
            left: 100px;
            width: 320px;
            height: 280px;
            font-size: 105px;
            font-weight: bold;
            line-height: 1;
        }
        .title-char {
            position: absolute;
            letter-spacing: 5px;
        }
        .char-cha { top: 0; left: 20px; }
        .char-yan { top: 0; left: 140px; }
        .char-yun { top: 125px; left: 0px; }
        .char-se { top: 135px; left: 160px; }

        .ph-leaves {
            position: absolute;
            top: -10px;
            left: -20px;
            width: 45px;
            height: 55px;
        }
        .ph-teaset {
            position: absolute;
            top: 100px;
            left: 30px;
            width: 80px;
            height: 45px;
            z-index: 2;
        }
        .ph-seal {
            position: absolute;
            top: 195px;
            left: 115px;
            width: 35px;
