        .top-right-header {
            position: absolute;
            top: 60px;
            right: 50px;
            text-align: right;
        }
        .exhib-title-zh {
            font-size: 20px;
            font-weight: bold;
            letter-spacing: 2px;
            margin-bottom: 8px;
        }
        .exhib-title-en {
            font-family: var(--font-en);
            font-size: 11px;
            letter-spacing: 2px;
            line-height: 1.5;
            color: #555;
        }

        /* Top Right - Intro Paragraph */
        .intro-text {
            position: absolute;
            top: 165px;
            right: 50px;
            text-align: right;
            font-size: 13px;
            line-height: 2.1;
            letter-spacing: 1.5px;
        }

        /* Middle Left - Dates */
        .date-section {
            position: absolute;
            top: 400px;
            left: 55px;
        }
        .date-year {
            font-size: 22px;
            font-weight: bold;
            letter-spacing: 2px;
            margin-bottom: 10px;
        }
        .date-row {
            display: flex;
            align-items: baseline;
            font-family: var(--font-en);
            font-size: 38px;
            font-weight: bold;
        }
        .date-day {
            font-size: 18px;
            margin-left: 10px;
            font-weight: normal;
        }
        .date-triangle {
            font-size: 14px;
            margin: 8px 0 8px 45px;
        }

        /* Middle Left - Location */
        .location-section {
            position: absolute;
            top: 620px;
            left: 55px;
        }
        .loc-title-row {
            display: flex;
            align-items: center;
            font-weight: bold;
            font-size: 20px;
            letter-spacing: 1px;
        }
        .pin-icon {
            display: inline-block;
            width: 12px;
            height: 12px;
            border: 2px solid var(--pin-gold);
            border-radius: 50% 50% 50% 0;
            transform: rotate(-45deg);
            margin-right: 12px;
            position: relative;
        }
        .pin-icon::after {
            content: '';
            position: absolute;
            width: 4px;
            height: 4px;
            background-color: var(--pin-gold);
            border-radius: 50%;
            top: 2px;
            left: 2px;
        }
        .loc-address {
            font-size: 15px;
            margin-top: 8px;
            margin-left: 28px;
            letter-spacing: 1px;
        }

        /* Middle Right - Ticket Info */
        .ticket-info {
            position: absolute;
            top: 395px;
            right: 50px;
            width: 330px;
            z-index: 10;
        }
        .ticket-row {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
        }
        .ticket-circle {
            width: 22px;
            height: 22px;
            border: 1px solid var(--text-dark);
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 12px;
            flex-shrink: 0;
        }
        .ticket-desc {
            flex: 1;
            margin-left: 12px;
            font-size: 13px;
            letter-spacing: 0.5px;
        }
        .ticket-price {
            font-family: var(--font-en);
            font-weight: bold;
            font-style: italic;
            font-size: 18px;
            white-space: nowrap;
        }
        .ticket-currency {
            font-family: var(--font-serif);
            font-style: normal;
            font-size: 13px;
            font-weight: normal;
            margin-left: 3px;
        }

        /* Large Leaf Painting Graphic */
        .leaf-graphic {
            position: absolute;
            bottom: 120px;
            right: -60px;
            width: 680px;
            height: 520px;
            border-radius: 100% 0 100% 0;
            z-index: 5;
        }

        /* Bottom Left - Footer */
        .footer-left {
            position: absolute;
            bottom: 40px;
            left: 45px;
            display: flex;
            align-items: center;
        }
        .ph-logo {
            width: 140px;
            height: 55px;
            margin-right: 25px;
        }
        .footer-contact {
            font-size: 11px;
            line-height: 1.7;
            letter-spacing: 0.5px;
            color: #333;
        }

        /* Bottom Right - Footer */
        .footer-right {
            position: absolute;
            bottom: 50px;
            right: 50px;
            text-align: right;
            color: var(--text-red);
            font-family: var(--font-en);
            font-size: 38px;
            font-weight: bold;
            line-height: 1.2;
            letter-spacing: 3px;
            z-index: 10;
        }
    </style>
</head>
